public class TileSetIDGridDecorator : GridDecorator<int>
{
	public string[,] tileLayerNames;
	public string tileLayerName = string.Empty;
	public string tileSetName = string.Empty;
	public bool markHasDoodad = true;
	public TileSetIDGridDecorator(int[,] tileSetIDs, string[,] tileLayerNames = null, string tileLayerName = "", string tileSetName = "", bool markHasDoodad = true)
		: base(tileSetIDs)
	{
		InitLayerData(tileLayerNames, tileLayerName, tileSetName, markHasDoodad);
	}
	public void InitLayerData(string[,] tileLayerNames = null, string tileLayerName = "", string tileSetName = "", bool markHasDoodad = true)
	{
		this.tileLayerNames = tileLayerNames;
		this.tileLayerName = tileLayerName;
		this.tileSetName = tileSetName;
		this.markHasDoodad = markHasDoodad;
	}
	public override void ApplyTileChanges(Tile tile, int decoRow, int decoCol)
	{
		if (grid[decoRow, decoCol] == 0)
		{
			return;
		}
		string text = tileLayerName;
		if (tileLayerName == string.Empty)
		{
			text = tileLayerNames[decoRow, decoCol];
		}
		if (!(text == string.Empty))
		{
			tile.layers[text].tileSetID = grid[decoRow, decoCol];
			if (markHasDoodad)
			{
				tile.layers[text].hasDoodad = true;
			}
			if (tileSetName != string.Empty)
			{
				tile.layers[text].tileSetName = tileSetName;
			}
		}
	}
}
